100	      transition: fill 0.35s cubic-bezier(0.34, 1.56, 0.64, 1), r 0.35s cubic-bezier(0.34, 1.56, 0.64, 1), stroke 0.35s ease, filter 0.35s ease, opacity 0.35s ease;
101	      will-change: fill, r, filter;
102	      contain: paint;
103	    }
104	    .circle-container:is(:hover, :focus-visible) circle {
105	      fill: #e8f4f8;
