592	  <main>
593	    <button type="button" class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to activate, double-click or tap twice to change color" aria-pressed="false" aria-expanded="false" aria-describedby="hint-text">
594	      <svg viewBox="0 0 400 400" preserveAspectRatio="xMidYMid meet" aria-hidden="true" role="presentation">
595	        <circle cx="200" cy="200" r="200"/>
596	      </svg>
597	    </button>
598	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
599	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click or tap to activate</div>
600	    <div class="controls" role="group" aria-label="Circle controls">
601	      <button type="button" class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
602	      <button type="button" class="control-btn" id="random-btn" aria-label="Jump to random color">Random</button>
603	      <button type="button" class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
604	    </div>
605	    <div class="keyboard-hint" aria-label="Keyboard shortcuts">Press <kbd>C</kbd> to cycle • <kbd>X</kbd> for random • <kbd>R</kbd> to reset • <kbd>?</kbd> for help</div>
606	  </main>
607	
608	  <script defer>
609	    (() => {
610	      const COLORS = [
611	        { class: 'default', name: 'Default White' },
612	        { class: 'color-mode-1', name: 'Pink' },
613	        { class: 'color-mode-2', name: 'Teal' },
614	        { class: 'color-mode-3', name: 'Mint' },
615	        { class: 'color-mode-4', name: 'Purple' },
616	        { class: 'color-mode-5', name: 'Orange' }
617	      ];
618	
619	      const getRandomColorMode = () => Math.floor(Math.random() * COLORS.length);
620	
621	      const CONFIG = {
622	        storageKey: 'circle-state',
623	        tapDelay: 300,
624	        colorShiftDuration: 500,
625	        saveDebounceDuration: 100,
626	        keyDebounce: 50,
627	        isTouch: (() => {
628	          const hasCoarsePointer = window.matchMedia?.('(pointer:coarse)').matches ?? false;
629	          const hasTouchEvents = 'ontouchstart' in window;
630	          const hasMaxTouchPoints = (navigator.maxTouchPoints ?? 0) > 0;
631	          return hasCoarsePointer || hasTouchEvents || hasMaxTouchPoints;
632	        })()
633	      };
634	
635	      const el = {
636	        circle: document.getElementById('decorative-circle'),
637	        hint: document.getElementById('hint-text'),
638	        modeIndicator: document.getElementById('mode-indicator'),
639	        cycleBtn: document.getElementById('cycle-btn'),
640	        randomBtn: document.getElementById('random-btn'),
641	        resetBtn: document.getElementById('reset-btn'),
642	        helpBtn: document.getElementById('help-btn'),
643	        helpModal: document.getElementById('help-modal'),
644	        modalClose: document.getElementById('modal-close')
645	      };
646	
647	      let state = { active: false, colorMode: 0 };
648	      let tapCount = 0;
649	      let tapTimeout = null;
650	      let animatingColorShift = false;
651	      let saveTimeout = null;
652	      let lastKeyTime = 0;
653	
654	      const haptic = (duration) => {
655	        try {
656	          navigator.vibrate?.(duration);
657	        } catch (e) {
658	          // Silently fail if vibration not available
659	        }
660	      };
661	
662	      const getColorClass = (mode) => COLORS[mode % COLORS.length]?.class || '';
663	      const getColorName = (mode) => COLORS[mode % COLORS.length]?.name || '';
664	
665	      const storage = {
666	        save() {
667	          clearTimeout(saveTimeout);
668	          saveTimeout = setTimeout(() => {
669	            try {
670	              localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
671	            } catch (e) {
672	              if (e?.name === 'QuotaExceededError') {
673	                console.warn('Storage quota exceeded');
674	              }
675	            }
676	          }, CONFIG.saveDebounceDuration);
677	        },
678	        load() {
679	          try {
680	            const saved = localStorage.getItem(CONFIG.storageKey);
681	            if (saved) {
682	              const parsed = JSON.parse(saved);
683	              if (parsed?.active !== undefined && parsed?.colorMode !== undefined) {
684	                state = parsed;
685	              }
686	            }
687	          } catch (e) {
688	            // Use default state on parse error
689	          }
690	        }
691	      };
692	
693	      const updateClasses = () => {
694	        if (!el.circle) return;
695	
696	        const colorClasses = COLORS.map(m => m.class);
697	        el.circle.classList.toggle('active', state.active);
698	        el.circle.setAttribute('aria-pressed', state.active.toString());
699	        el.circle.setAttribute('aria-expanded', (state.colorMode > 0).toString());
700	
701	        colorClasses.forEach(cls => {
702	          el.circle.classList.remove(cls);
703	        });
704	
705	        if (state.colorMode > 0) {
706	          el.circle.classList.add(getColorClass(state.colorMode));
707	        }
708	      };
709	
710	      const updateUI = () => {
711	        const hint = CONFIG.isTouch
712	          ? (state.active ? 'Tap twice to cycle • Tap to deactivate' : 'Tap to activate • Tap twice to cycle')
713	          : (state.active ? 'Double-click to cycle • Click to deactivate' : 'Click to activate • Double-click to cycle');
714	        el.hint.textContent = hint;
715	
716	        const showMode = state.active && state.colorMode > 0;
717	        el.modeIndicator.classList.toggle('visible', showMode);
718	        if (showMode) {
719	          el.modeIndicator.textContent = `◆ ${getColorName(state.colorMode).toUpperCase()}`;
720	        }
721	      };
722	
723	      const applyState = () => {
724	        updateClasses();
725	        updateUI();
726	      };
727	
728	      const modal = {
729	        open: () => {
730	          if (!el.helpModal || !el.modalClose) return;
731	          el.helpModal.classList.add('active');
732	          el.modalClose.focus();
733	        },
734	        close: () => {
735	          if (!el.helpModal) return;
736	          el.helpModal.classList.remove('active');
737	          if (el.helpBtn) el.helpBtn.focus();
738	        }
739	      };
740	
741	      const toggleActive = () => {
742	        state.active = !state.active;
743	        haptic(10);
744	        applyState();
745	        storage.save();
746	      };
747	
748	      const cycleColor = () => {
749	        if (animatingColorShift || !el.circle) return;
750	
751	        animatingColorShift = true;
752	        state.colorMode = (state.colorMode + 1) % COLORS.length;
753	        state.active = true;
754	        haptic(20);
755	        el.circle.classList.add('color-shifting');
756	        setTimeout(() => {
757	          el.circle.classList.remove('color-shifting');
758	          animatingColorShift = false;
759	        }, CONFIG.colorShiftDuration);
760	        applyState();
761	        storage.save();
762	      };
763	
764	      const randomizeColor = () => {
765	        if (animatingColorShift || !el.circle) return;
766	
767	        animatingColorShift = true;
768	        state.colorMode = getRandomColorMode();
769	        state.active = true;
770	        haptic([20, 10, 20]);
771	        el.circle.classList.add('color-shifting');
772	        setTimeout(() => {
773	          el.circle.classList.remove('color-shifting');
774	          animatingColorShift = false;
775	        }, CONFIG.colorShiftDuration);
776	        applyState();
777	        storage.save();
778	      };
779	
780	      const resetState = () => {
781	        state = { active: false, colorMode: 0 };
782	        haptic(10);
783	        applyState();
784	        storage.save();
785	      };
786	
787	      const handleTouchEnd = () => {
788	        tapCount++;
789	        haptic(10);
790	        clearTimeout(tapTimeout);
791	
792	        if (tapCount === 1) {
793	          tapTimeout = setTimeout(() => {
794	            if (tapCount === 1) {
795	              toggleActive();
796	            }
797	            tapCount = 0;
798	          }, CONFIG.tapDelay);
799	        } else if (tapCount >= 2) {
800	          tapCount = 0;
801	          cycleColor();
802	        }
803	      };
804	
805	      const keyHandlers = {
806	        ' ': toggleActive,
807	        'enter': toggleActive,
808	        'escape': resetState,
809	        'c': cycleColor,
810	        'x': randomizeColor,
811	        'r': resetState,
812	        '?': modal.open
813	      };
814	
815	      const handleKeyDown = (e) => {
816	        const key = e.key.toLowerCase();
817	        const handler = keyHandlers[key];
818	        if (!handler) return;
819	
820	        const now = Date.now();
821	        if (now - lastKeyTime < CONFIG.keyDebounce) return;
822	
823	        e.preventDefault();
824	        try {
825	          handler();
826	          lastKeyTime = now;
827	        } catch (err) {
828	          console.error('Keyboard handler error:', err);
829	        }
830	      };
831	
832	      const handleModalKeyDown = (e) => {
833	        if (e.key === 'Escape') {
834	          e.preventDefault();
835	          modal.close();
836	        }
837	      };
838	
839	      const handleModalBackdropClick = (e) => {
840	        if (e.target === el.helpModal) {
841	          modal.close();
842	        }
843	      };
844	
845	      const initListeners = () => {
846	        if (!el.circle) return;
847	
848	        el.circle.addEventListener('blur', () => {
849	          tapCount = 0;
850	          clearTimeout(tapTimeout);
851	        });
852	
853	        if (CONFIG.isTouch) {
854	          el.circle.addEventListener('touchend', handleTouchEnd, { passive: true });
855	          if (window.PointerEvent) {
856	            el.circle.addEventListener('pointerup', handleTouchEnd, { passive: true });
857	          }
858	        } else {
859	          el.circle.addEventListener('click', toggleActive, { passive: true });
860	          el.circle.addEventListener('dblclick', cycleColor, { passive: true });
861	        }
862	
863	        document.addEventListener('keydown', handleKeyDown);
864	
865	        el.cycleBtn?.addEventListener('click', cycleColor, { passive: true });
866	        el.randomBtn?.addEventListener('click', randomizeColor, { passive: true });
867	        el.resetBtn?.addEventListener('click', resetState, { passive: true });
868	        el.helpBtn?.addEventListener('click', modal.open, { passive: true });
869	        el.modalClose?.addEventListener('click', modal.close, { passive: true });
870	        el.helpModal?.addEventListener('click', handleModalBackdropClick, { passive: true });
871	        el.helpModal?.addEventListener('keydown', handleModalKeyDown);
872	      };
873	
874	      const initApp = () => {
875	        if (!el.circle) {
876	          console.error('Circle element not found');
877	          return;
878	        }
879	        storage.load();
880	        applyState();
881	        initListeners();
882	        el.circle.focus?.();
883	      };
884	
885	      const ensureSave = () => {
886	        clearTimeout(saveTimeout);
887	        try {
888	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
889	        } catch (e) {
890	          // Silently fail on storage errors during page hide
891	        }
892	      };
893	
894	      if (document.readyState === 'loading') {
895	        document.addEventListener('DOMContentLoaded', initApp);
896	      } else {
897	        initApp();
898	      }
899	
900	      window.addEventListener('pagehide', ensureSave);
901	    })();
902	  </script>
903	</body>
